"""PLINK arm on the exact 37566-site BED generated by the reviewed pilot."""
from pathlib import Path
import sys
if not __debug__:
    raise RuntimeError('Optimized Python disables required scientific assertions; run without -O.')
_HELPER_DIR = str(Path(__file__).resolve().parent)
if _HELPER_DIR not in sys.path:
    sys.path.insert(0, _HELPER_DIR)
import datetime,hashlib,json,subprocess,sys,time
HERE=Path(__file__).resolve().parent
PROGRAM=None
EXPECTED='47ec461f1768cce1529e226654329268eacd9ca96ee62db4558fa04c4c3d51e4'
DEFAULT_EXPECTED=EXPECTED
OPTIONS=['--allow-extra-chr','--keep-allele-order','--threads','2','--memory','3500','--pca','14','header','tabs','--make-rel','square','--missing','--freqx']
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def execute(root, out):
 r=json.loads((root/'RUN_RECEIPT.json').read_text())
 assert r['status'] in ('COMPLETED_PENDING_ROOT_SCIENTIFIC_AUDIT','PARTIAL_PENDING_ROOT_SCIENTIFIC_AUDIT') and r['selected_sites']==37566 and len(r['samples'])==14
 assert sha(PROGRAM)==EXPECTED
 inputs={n:sha(root/n) for n in ['paired.bed','paired.bim','paired.fam']}
 expected={x['path']:x['sha256'] for x in r['output_files']}
 assert all(h==expected[n] for n,h in inputs.items())
 out.mkdir(parents=True,exist_ok=False)
 command=[str(PROGRAM),*OPTIONS,'--bfile',str(root/'paired'),'--out',str(out/'pca')]
 record={'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'command':command,'binary_sha256':EXPECTED,'input_hashes_before':inputs,'runner_sha256':sha(Path(__file__)),'source_pilot_receipt_sha256':sha(root/'RUN_RECEIPT.json'),'status':'RUNNING','no_new_site_or_sample_filter':True}
 t=time.monotonic()
 try:
  with (out/'stdout.log').open('x') as log:
   p=subprocess.run(command,stdout=log,stderr=subprocess.STDOUT)
  record['exit_code']=p.returncode;p.check_returncode()
  record['input_hashes_after']={n:sha(root/n) for n in inputs}
  assert record['input_hashes_after']==inputs
  lines=(out/'pca.eigenvec').read_text().splitlines()
  assert len(lines)==15 and [x.split()[1] for x in lines[1:]]==r['samples']
  assert len((out/'pca.eigenval').read_text().splitlines())==14
  assert '37566 variants and 14 people pass filters and QC.' in (out/'pca.log').read_text()
  record['status']='COMPLETED_PENDING_INDEPENDENT_AUDIT'
 except Exception as error:
  record['status']='FAILED';record['error']=str(error);raise
 finally:
  record['seconds']=time.monotonic()-t
  record['outputs']=[{'path':p.name,'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(out.iterdir()) if p.is_file()]
  (out/'RECEIPT.json').write_text(json.dumps(record,indent=2,allow_nan=False)+'\n')
 print(json.dumps(record))

def configure(config, base):
 from _population_cli import path_value, require_file, require_directory, fresh_output, expected_hash
 global PROGRAM, EXPECTED
 root=require_directory(path_value(config,'run_root',base))
 PROGRAM=require_file(path_value(config,'plink',base),executable=True)
 EXPECTED=config.get('plink_sha256',DEFAULT_EXPECTED)
 expected_hash(PROGRAM,EXPECTED,'PLINK binary')
 out=fresh_output(path_value(config,'outdir',base),[root/'paired.bed',root/'paired.bim',root/'paired.fam'])
 return root,out

def preflight(root,out):
 from _population_cli import report_plan
 r=json.loads((root/'RUN_RECEIPT.json').read_text())
 assert r['status'] in ('COMPLETED_PENDING_ROOT_SCIENTIFIC_AUDIT','PARTIAL_PENDING_ROOT_SCIENTIFIC_AUDIT') and r['selected_sites']==37566 and len(r['samples'])==14
 expected={x['path']:x['sha256'] for x in r['output_files']}
 for n in ['paired.bed','paired.bim','paired.fam']:assert sha(root/n)==expected[n]
 return report_plan('run_plink_arm.py',{'receipt':root/'RUN_RECEIPT.json','plink':PROGRAM,**{n:root/n for n in ['paired.bed','paired.bim','paired.fam']}},{n:out/n for n in ['RECEIPT.json','pca.rel','pca.eigenvec','pca.eigenval','pca.log']},required_threads=2,command=[str(PROGRAM),*OPTIONS,'--bfile',str(root/'paired'),'--out',str(out/'pca')])

def plan(config_path):
    """Return a read-only, JSON-compatible artifact and dependency plan."""
    config_path=Path(config_path).resolve();config=json.loads(config_path.read_text());root,out=configure(config,config_path.parent);return preflight(root,out)


def main(argv=None):
 from _population_cli import read_config
 config,base,run=read_config(__doc__,argv);root,out=configure(config,base);print(json.dumps(preflight(root,out),indent=2))
 if run:execute(root,out)
 return 0

if __name__=='__main__':raise SystemExit(main())
